16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	import java.util.Optional;
20	
21	/**
22	 * The Australian region an owner's city belongs to. Each constant's name is the canonical region
23	 * code as stored and returned (e.g. {@code "NSW"}). Regions are resolved from a single fixed
24	 * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD});
25	 * a city that is not in the table has no known region.
26	 *
27	 * <p>This is the one place the city-to-region mapping lives, so every rule that keys off an owner's
28	 * region - such as the derived {@code locality} - resolves it identically.
29	 */
30	public enum Region {
31	
32	    NSW(2000, 2099, "Australia/Sydney"),
33	    VIC(3000, 3099, "Australia/Melbourne"),
34	    QLD(4000, 4099, "Australia/Brisbane");
35	
36	    private final int minPostcode;
37	
38	    private final int maxPostcode;
39	
40	    private final String timezone;
41	
42	    Region(int minPostcode, int maxPostcode, String timezone) {
43	        this.minPostcode = minPostcode;
44	        this.maxPostcode = maxPostcode;
45	        this.timezone = timezone;
46	    }
47	
48	    /**
49	     * Returns this region's IANA timezone name from the fixed region-to-timezone table
50	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
51	     * {@code QLD -> Australia/Brisbane}).
52	     *
53	     * @return the region's IANA timezone name
54	     */
55	    public String timezone() {
56	        return this.timezone;
57	    }
58	
59	    /**
60	     * Resolves the IANA timezone name for the given canonical region code from the fixed
61	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
62	     * {@code QLD -> Australia/Brisbane}). This is the one place the region-to-timezone mapping lives,
63	     * so every rule that labels an owner by timezone resolves it identically.
64	     *
65	     * @param code the canonical region code (e.g. {@code "NSW"}), or {@code null}
66	     * @return the matching IANA timezone name, or {@code null} when the code is {@code null} or has no
67	     *         known timezone (such as {@link #UNKNOWN_CODE})
68	     */
69	    public static String timezoneForCode(String code) {
70	        return forCode(code).map(Region::timezone).orElse(null);
71	    }
72	
73	    /** Fixed city -> region table; a city absent from this map has no known region. */
74	    private static final Map<String, Region> BY_CITY = Map.of(
75	        "Sydney", NSW,
76	        "Melbourne", VIC,
77	        "Brisbane", QLD);
78	
79	    /** Canonical region code returned when neither the postcode nor the city resolves to a region. */
80	    public static final String UNKNOWN_CODE = "UNKNOWN";
81	
82	    /**
83	     * Reports whether the given 4-digit postcode falls within this region's inclusive postcode range
84	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). This is the one place the region-to-postcode
85	     * range lives, so every rule that validates a postcode against an owner's region resolves it
86	     * identically.
87	     *
88	     * @param postcode the numeric value of the owner's 4-digit postcode
89	     * @return {@code true} when the postcode is within this region's range
90	     */
91	    public boolean acceptsPostcode(int postcode) {
92	        return postcode >= this.minPostcode && postcode <= this.maxPostcode;
93	    }
94	
95	    /**
96	     * Resolves the region named by the given canonical region code (e.g. {@code "NSW"}) by matching it
97	     * against the region constants' {@linkplain #name() names}. This is the by-code counterpart of
98	     * {@link #forCity(String)} and {@link #forPostcode(String)}, for a value that is already a region
99	     * code rather than a city or postcode, and is the one place a code is turned back into its
100	     * {@link Region}, so every rule that keys off a region code resolves it identically.
101	     *
102	     * @param code the canonical region code (e.g. {@code "NSW"}), or {@code null}
103	     * @return the matching region, or empty when the code is {@code null} or names no known region
104	     *         (such as {@link #UNKNOWN_CODE})
105	     */
106	    public static Optional<Region> forCode(String code) {
107	        if (code == null) {
108	            return Optional.empty();
109	        }
110	        for (Region region : values()) {
111	            if (region.name().equals(code)) {
112	                return Optional.of(region);
113	            }
114	        }
115	        return Optional.empty();
116	    }
117	
118	    /**
119	     * Resolves the region for the given city from the fixed city-to-region table.
120	     *
121	     * @param city the owner's city, or {@code null}
122	     * @return the matching region, or empty when the city is {@code null} or has no known region
123	     */
124	    public static Optional<Region> forCity(String city) {
125	        return city == null ? Optional.empty() : Optional.ofNullable(BY_CITY.get(city));
126	    }
127	
128	    /**
129	     * Resolves the region whose postcode range contains the given 4-digit postcode
130	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
131	     *
132	     * @param postcode the owner's 4-digit postcode, or {@code null}
133	     * @return the matching region, or empty when the postcode is {@code null}, not numeric, or in no
134	     *         known range
135	     */
136	    public static Optional<Region> forPostcode(String postcode) {
137	        if (postcode == null) {
138	            return Optional.empty();
139	        }
140	        int value;
141	        try {
142	            value = Integer.parseInt(postcode.trim());
143	        } catch (NumberFormatException ex) {
144	            return Optional.empty();
145	        }
146	        for (Region region : values()) {
147	            if (region.acceptsPostcode(value)) {
148	                return Optional.of(region);
149	            }
150	        }
151	        return Optional.empty();
152	    }
153	
154	    /**
155	     * Resolves the canonical region code for an owner located at the given {@code postcode} and
156	     * {@code city}, preferring the postcode: it first looks up the region by
157	     * {@link #forPostcode(String) postcode range} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and
158	     * only falls back to the {@link #forCity(String) city-to-region} table ({@code Sydney -> NSW},
159	     * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is absent or in no known
160	     * range. Returns the region's code, or {@link #UNKNOWN_CODE} when neither resolves.
161	     *
162	     * <p>This is the one place an owner's postcode and city are turned into a region code, so every
163	     * rule that labels an owner by region resolves it identically.
164	     *
165	     * @param postcode the owner's 4-digit postcode, or {@code null}
166	     * @param city the owner's city, or {@code null}
167	     * @return the canonical region code, or {@link #UNKNOWN_CODE} when neither postcode nor city resolves
168	     */
169	    public static String code(String postcode, String city) {
170	        return forPostcode(postcode)
171	            .or(() -> forCity(city))
172	            .map(Region::name)
173	            .orElse(UNKNOWN_CODE);
174	    }
175	}
