16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "postcode")
57	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
58	    private String postcode;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form ('+' and 8 to 15 digits)")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    @Email
67	    private String email;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    /**
85	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
86	     * including this owner). Derived at read time and not persisted; an owner with no household
87	     * counts as a household of one. Feeds the household factor of the membership points.
88	     */
89	    @Transient
90	    private int householdSize = 1;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted", nullable = false)
96	    private boolean deleted = false;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    public String getTitle() {
102	        return this.title;
103	    }
104	
105	    public void setTitle(String title) {
106	        this.title = title;
107	    }
108	
109	    public String getAddress() {
110	        return this.address;
111	    }
112	
113	    public void setAddress(String address) {
114	        this.address = address;
115	    }
116	
117	    public String getAddressLine1() {
118	        return this.addressLine1;
119	    }
120	
121	    public void setAddressLine1(String addressLine1) {
122	        this.addressLine1 = addressLine1;
123	    }
124	
125	    public String getAddressLine2() {
126	        return this.addressLine2;
127	    }
128	
129	    public void setAddressLine2(String addressLine2) {
130	        this.addressLine2 = addressLine2;
131	    }
132	
133	    public String getCity() {
134	        return this.city;
135	    }
136	
137	    public void setCity(String city) {
138	        this.city = city;
139	    }
140	
141	    public String getPostcode() {
142	        return this.postcode;
143	    }
144	
145	    public void setPostcode(String postcode) {
146	        this.postcode = postcode;
147	    }
148	
149	    public String getTelephone() {
150	        return this.telephone;
151	    }
152	
153	    public void setTelephone(String telephone) {
154	        this.telephone = telephone;
155	    }
156	
157	    public String getEmail() {
158	        return this.email;
159	    }
160	
161	    public void setEmail(String email) {
162	        this.email = email;
163	    }
164	
165	    public LocalDate getRegistrationDate() {
166	        return this.registrationDate;
167	    }
168	
169	    public void setRegistrationDate(LocalDate registrationDate) {
170	        this.registrationDate = registrationDate;
171	    }
172	
173	    public LocalDate getBirthDate() {
174	        return this.birthDate;
175	    }
176	
177	    public void setBirthDate(LocalDate birthDate) {
178	        this.birthDate = birthDate;
179	    }
180	
181	    public String getCustomerCode() {
182	        return this.customerCode;
183	    }
184	
185	    public void setCustomerCode(String customerCode) {
186	        this.customerCode = customerCode;
187	    }
188	
189	    public String getHouseholdId() {
190	        return this.householdId;
191	    }
192	
193	    public void setHouseholdId(String householdId) {
194	        this.householdId = householdId;
195	    }
196	
197	    public Integer getNamesakeCount() {
198	        return this.namesakeCount;
199	    }
200	
201	    public void setNamesakeCount(Integer namesakeCount) {
202	        this.namesakeCount = namesakeCount;
203	    }
204	
205	    public int getHouseholdSize() {
206	        return this.householdSize;
207	    }
208	
209	    public void setHouseholdSize(int householdSize) {
210	        this.householdSize = householdSize;
211	    }
212	
213	    public Integer getPossibleDuplicateOf() {
214	        return this.possibleDuplicateOf;
215	    }
216	
217	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
218	        this.possibleDuplicateOf = possibleDuplicateOf;
219	    }
220	
221	    public boolean isDeleted() {
222	        return this.deleted;
223	    }
224	
225	    public void setDeleted(boolean deleted) {
226	        this.deleted = deleted;
227	    }
228	
229	    protected Set<Pet> getPetsInternal() {
230	        if (this.pets == null) {
231	            this.pets = new HashSet<>();
232	        }
233	        return this.pets;
234	    }
235	
236	    protected void setPetsInternal(Set<Pet> pets) {
237	        this.pets = pets;
238	    }
239	
240	    public List<Pet> getPets() {
241	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
242	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
243	        return Collections.unmodifiableList(sortedPets);
244	    }
245	
246	    public void setPets(List<Pet> pets) {
247	        this.pets = new HashSet<>(pets);
248	    }
249	
250	    public void addPet(Pet pet) {
251	        getPetsInternal().add(pet);
252	        pet.setOwner(this);
253	    }
254	
255	    /**
256	     * Return the Pet with the given name, or null if none found for this Owner.
257	     *
258	     * @param name to test
259	     * @return true if pet name is already in use
260	     */
261	    public Pet getPet(String name) {
262	        return getPet(name, false);
263	    }
264	
265	    /**
266	     * Return the Pet with the given name, or null if none found for this Owner.
267	     *
268	     * @param name to test
269	     * @return true if pet name is already in use
270	     */
271	    public Pet getPet(String name, boolean ignoreNew) {
272	        name = name.toLowerCase();
273	        for (Pet pet : getPetsInternal()) {
274	            if (!ignoreNew || !pet.isNew()) {
275	                String compName = pet.getName();
276	                compName = compName.toLowerCase();
277	                if (compName.equals(name)) {
278	                    return pet;
279	                }
280	            }
281	        }
282	        return null;
283	    }
284	
285	    public Pet getPet(Integer petId) {
286	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
287	    }
288	
289	    @Override
290	    public String toString() {
291	        return new ToStringCreator(this)
292	
293	            .append("id", this.getId())
294	            .append("new", this.isNew())
295	            .append("lastName", this.getLastName())
296	            .append("firstName", this.getFirstName())
297	            .append("address", this.address)
298	            .append("city", this.city)
299	            .append("telephone", this.telephone)
300	            .toString();
301	    }
302	}
