17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity (telephone, email and household) already exists";
57	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
58	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
59	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date must not be later than the current server date";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Builds a 409 Conflict response for a create request that collides with an existing owner. The
81	     * body is a {@link ProblemDetail} carrying {@code detail} and an {@code errors} array naming the
82	     * conflicting fields, matching the shape produced for the other owner-creation error responses.
83	     *
84	     * @param e Object referring to the thrown exception.
85	     * @param request {@link HttpServletRequest} object referring to the current request.
86	     * @param detail the human-readable detail message.
87	     * @param errors the names of the fields whose values conflicted.
88	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
89	     */
90	    private ResponseEntity<ProblemDetail> conflict(Exception e, HttpServletRequest request, String detail, List<String> errors) {
91	        HttpStatus status = HttpStatus.CONFLICT;
92	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
93	        problemDetail.setProperty("errors", errors);
94	        return ResponseEntity.status(status).body(problemDetail);
95	    }
96	
97	    /**
98	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
99	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
100	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
101	     * would catch it and report an authorization failure as a 500.
102	     *
103	     * @param e The {@link AccessDeniedException} to propagate
104	     * @throws AccessDeniedException always
105	     */
106	    @ExceptionHandler(AccessDeniedException.class)
107	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
108	        throw e;
109	    }
110	
111	    /**
112	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
113	     *
114	     * @param e The {@link Exception} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
117	     */
118	    @ExceptionHandler(Exception.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
121	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
122	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
123	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
124	        return ResponseEntity.status(status).body(detail);
125	    }
126	
127	    /**
128	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
129	     * method returns a 404 Not Found status if an entity does not exist.
130	     *
131	     * @param e The {@link DataIntegrityViolationException} to be handled
132	     * @param request {@link HttpServletRequest} object referring to the current request.
133	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
134	     */
135	    @ExceptionHandler(DataIntegrityViolationException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
138	        logger.warn("Data integrity violation at {} {}: {}",
139	            request.getMethod(),
140	            request.getRequestURI(),
141	            e.getMessage());
142	        logger.debug("Data integrity violation stacktrace", e);
143	        HttpStatus status = HttpStatus.NOT_FOUND;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
145	        return ResponseEntity.status(status).body(detail);
146	    }
147	
148	    /**
149	     * Handles exception thrown by Bean Validation on controller methods parameters
150	     *
151	     * @param e The {@link MethodArgumentNotValidException} to be handled
152	     * @param request {@link HttpServletRequest} object referring to the current request.
153	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
154	     */
155	    @ExceptionHandler(MethodArgumentNotValidException.class)
156	    @ResponseBody
157	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
158	        HttpStatus status = HttpStatus.BAD_REQUEST;
159	        BindingErrorsResponse errors = new BindingErrorsResponse();
160	        BindingResult bindingResult = e.getBindingResult();
161	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
162	        if (bindingResult.hasErrors()) {
163	            errors.addAllErrors(bindingResult);
164	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
165	                .map(FieldError::getField)
166	                .distinct()
167	                .toList();
168	            detail.setProperty("errors", invalidFields);
169	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
170	                .map(fieldError -> {
171	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
172	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
173	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
174	                        fieldError.getField(),
175	                        defaultMessage,
176	                        rejectedValue);
177	                    return new ValidationMessageDto(message)
178	                        .putAdditionalProperty("field", fieldError.getField())
179	                        .putAdditionalProperty("rejectedValue", rejectedValue)
180	                        .putAdditionalProperty("defaultMessage", defaultMessage);
181	                })
182	                .toList();
183	            logger.debug("Validation error at {} {}: {}",
184	                request.getMethod(),
185	                request.getRequestURI(),
186	                bindingResult.getFieldErrors());
187	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
188	            return ResponseEntity.status(status).body(detail);
189	        }
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidOwnerFieldsException} raised when an owner has required fields that are
195	     * present but blank (whitespace-only). Returns a 400 Bad Request whose body carries an
196	     * {@code errors} array listing the name of each blank field, mirroring the shape produced for
197	     * Bean Validation failures.
198	     *
199	     * @param e The {@link InvalidOwnerFieldsException} to be handled
200	     * @param request {@link HttpServletRequest} object referring to the current request.
201	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
202	     */
203	    @ExceptionHandler(InvalidOwnerFieldsException.class)
204	    @ResponseBody
205	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
206	        HttpStatus status = HttpStatus.BAD_REQUEST;
207	        logger.debug("Blank owner fields at {} {}: {}",
208	            request.getMethod(),
209	            request.getRequestURI(),
210	            e.getFields());
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
212	        detail.setProperty("errors", e.getFields());
213	        return ResponseEntity.status(status).body(detail);
214	    }
215	
216	    /**
217	     * Handles {@link InvalidOwnerPostcodeException} raised when an owner submitted to the create
218	     * endpoint carries a well-formed 4-digit {@code postcode} that is out of range for the owner's
219	     * city region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Returns a 400 Bad Request whose body
220	     * carries an {@code errors} array naming the {@code postcode} field, mirroring the shape produced
221	     * for Bean Validation failures.
222	     *
223	     * @param e The {@link InvalidOwnerPostcodeException} to be handled
224	     * @param request {@link HttpServletRequest} object referring to the current request.
225	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
226	     */
227	    @ExceptionHandler(InvalidOwnerPostcodeException.class)
228	    @ResponseBody
229	    public ResponseEntity<ProblemDetail> handleInvalidOwnerPostcodeException(InvalidOwnerPostcodeException e, HttpServletRequest request) {
230	        HttpStatus status = HttpStatus.BAD_REQUEST;
231	        logger.debug("Invalid owner postcode at {} {}: {}",
232	            request.getMethod(),
233	            request.getRequestURI(),
234	            e.getMessage());
235	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
236	        detail.setProperty("errors", List.of("postcode"));
237	        return ResponseEntity.status(status).body(detail);
238	    }
239	
240	    /**
241	     * Handles {@link DisposableEmailDomainException} raised when an owner submitted to the create
242	     * endpoint carries an {@code email} whose domain is on the disposable-domain blocklist
243	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Returns a 400 Bad
244	     * Request whose body carries an {@code errors} array naming the {@code email} field, mirroring
245	     * the shape produced for Bean Validation failures.
246	     *
247	     * @param e The {@link DisposableEmailDomainException} to be handled
248	     * @param request {@link HttpServletRequest} object referring to the current request.
249	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
250	     */
251	    @ExceptionHandler(DisposableEmailDomainException.class)
252	    @ResponseBody
253	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
254	        HttpStatus status = HttpStatus.BAD_REQUEST;
255	        logger.debug("Disposable owner email domain at {} {}: {}",
256	            request.getMethod(),
257	            request.getRequestURI(),
258	            e.getMessage());
259	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
260	        detail.setProperty("errors", List.of("email"));
261	        return ResponseEntity.status(status).body(detail);
262	    }
263	
264	    /**
265	     * Handles {@link DuplicateOwnerIdentityException} raised when an owner submitted to the create
266	     * endpoint has a derived identity key (normalized telephone, email and household id) that exactly
267	     * equals an existing owner's. This single key consolidates the former separate telephone, email
268	     * and household duplicate checks. Returns a 409 Conflict.
269	     *
270	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
271	     * @param request {@link HttpServletRequest} object referring to the current request.
272	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
273	     */
274	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
275	    @ResponseBody
276	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
277	        logger.debug("Duplicate owner identity at {} {}: {}",
278	            request.getMethod(),
279	            request.getRequestURI(),
280	            e.getIdentityKey());
281	        return this.conflict(e, request, ERROR_DUPLICATE_IDENTITY, List.of("identityKey"));
282	    }
283	
284	    /**
285	     * Handles {@link OwnerCityAtCapacityException} raised when an owner submitted to the create
286	     * endpoint would be placed in a city that already contains the maximum number of owners (50 or
287	     * more). Returns a 409 Conflict.
288	     *
289	     * @param e The {@link OwnerCityAtCapacityException} to be handled
290	     * @param request {@link HttpServletRequest} object referring to the current request.
291	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
292	     */
293	    @ExceptionHandler(OwnerCityAtCapacityException.class)
294	    @ResponseBody
295	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
296	        logger.debug("Owner city at capacity at {} {}: {}",
297	            request.getMethod(),
298	            request.getRequestURI(),
299	            e.getCity());
300	        return this.conflict(e, request, ERROR_CITY_AT_CAPACITY, List.of("city"));
301	    }
302	
303	    /**
304	     * Handles {@link DailyOwnerRegistrationLimitException} raised when an owner submitted to the
305	     * create endpoint would exceed the maximum number of owners that may be registered on a single
306	     * day (100 or more owners already carry today's {@code registrationDate}). Returns a
307	     * 429 Too Many Requests whose body carries an {@code errors} array naming the
308	     * {@code registrationDate} field, matching the shape produced for the other owner-creation error
309	     * responses.
310	     *
311	     * @param e The {@link DailyOwnerRegistrationLimitException} to be handled
312	     * @param request {@link HttpServletRequest} object referring to the current request.
313	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
314	     */
315	    @ExceptionHandler(DailyOwnerRegistrationLimitException.class)
316	    @ResponseBody
317	    public ResponseEntity<ProblemDetail> handleDailyOwnerRegistrationLimitException(DailyOwnerRegistrationLimitException e, HttpServletRequest request) {
318	        logger.debug("Daily owner registration limit reached at {} {}: {}",
319	            request.getMethod(),
320	            request.getRequestURI(),
321	            e.getDate());
322	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
323	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
324	        detail.setProperty("errors", List.of("registrationDate"));
325	        return ResponseEntity.status(status).body(detail);
326	    }
327	
328	    /**
329	     * Handles {@link FutureRegistrationDateException} raised when an owner submitted to the create
330	     * endpoint carries a {@code registrationDate} that is later than the server's current date.
331	     * Returns a 400 Bad Request whose body carries an {@code errors} array naming the
332	     * {@code registrationDate} field, mirroring the shape produced for the other owner-creation
333	     * error responses.
334	     *
335	     * @param e The {@link FutureRegistrationDateException} to be handled
336	     * @param request {@link HttpServletRequest} object referring to the current request.
337	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
338	     */
339	    @ExceptionHandler(FutureRegistrationDateException.class)
340	    @ResponseBody
341	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
342	        HttpStatus status = HttpStatus.BAD_REQUEST;
343	        logger.debug("Future registration date at {} {}: {}",
344	            request.getMethod(),
345	            request.getRequestURI(),
346	            e.getRegistrationDate());
347	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
348	        detail.setProperty("errors", List.of("registrationDate"));
349	        return ResponseEntity.status(status).body(detail);
350	    }
351	
352	}
