52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
54	import org.springframework.samples.petclinic.rest.advice.DisposableEmailDomainException;
55	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
56	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
57	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
58	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerPostcodeException;
59	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
