67	import org.springframework.web.bind.annotation.CrossOrigin;
68	import org.springframework.web.bind.annotation.RequestMapping;
69	import org.springframework.web.bind.annotation.RestController;
70	import org.springframework.web.context.request.RequestContextHolder;
71	import org.springframework.web.context.request.ServletRequestAttributes;
72	import org.springframework.web.util.UriComponentsBuilder;
73	
74	import jakarta.transaction.Transactional;
75	
76	/**
77	 * @author Vitaliy Fedoriv
78	 */
79	
80	@RestController
81	@CrossOrigin(exposedHeaders = "errors, content-type")
82	@RequestMapping("/api")
83	public class OwnerRestControllerV1 implements OwnersApi {
84	
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    /**
88	     * Serializes {@link OwnerCreatedEvent}s to the JSON carried on the {@code AUDIT} logger. A single
89	     * shared, thread-safe mapper so every structured audit event is rendered identically.
90	     */
91	    private static final ObjectMapper AUDIT_MAPPER = new ObjectMapper();
92	
93	    /**
94	     * Monotonically increasing sequence assigned to each owner create, carried as the {@code seq} of
95	     * the emitted {@link OwnerCreatedEvent} so the ordering of creates can be reconstructed from the
96	     * audit stream. Held per JVM and incremented atomically so concurrent creates receive distinct,
97	     * strictly increasing values.
98	     */
99	    private static final AtomicLong CREATE_SEQUENCE = new AtomicLong();
100	
101	    private final ClinicService clinicService;
102	
103	    private final OwnerMapper ownerMapper;
104	
105	    private final PetMapper petMapper;
106	
107	    private final VisitMapper visitMapper;
108	
109	    private final TelephoneNormalizer telephoneNormalizer;
110	
111	    private final AddressNormalizer addressNormalizer;
112	
113	    private final EmailNormalizer emailNormalizer;
114	
115	    private final DisposableEmailDomains disposableEmailDomains;
116	
117	    private final Sha256Hasher sha256Hasher;
118	
119	    private final Soundex soundex;
120	
121	    private final IdempotencyKeyStore idempotencyKeyStore;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper,
127	                                 TelephoneNormalizer telephoneNormalizer,
128	                                 AddressNormalizer addressNormalizer,
129	                                 EmailNormalizer emailNormalizer,
130	                                 DisposableEmailDomains disposableEmailDomains,
131	                                 Sha256Hasher sha256Hasher,
132	                                 Soundex soundex,
133	                                 IdempotencyKeyStore idempotencyKeyStore) {
134	        this.clinicService = clinicService;
135	        this.ownerMapper = ownerMapper;
136	        this.petMapper = petMapper;
137	        this.visitMapper = visitMapper;
138	        this.telephoneNormalizer = telephoneNormalizer;
139	        this.addressNormalizer = addressNormalizer;
140	        this.emailNormalizer = emailNormalizer;
141	        this.disposableEmailDomains = disposableEmailDomains;
142	        this.sha256Hasher = sha256Hasher;
143	        this.soundex = soundex;
144	        this.idempotencyKeyStore = idempotencyKeyStore;
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
150	        Collection<Owner> owners;
151	        if (lastName != null) {
152	            owners = this.clinicService.findOwnerByLastName(lastName);
153	        } else {
154	            owners = this.clinicService.findAllOwners();
155	        }
156	        if (owners.isEmpty()) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
165	        return withOwner(ownerId, owner ->
166	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
167	    }
168	
169	    /**
170	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
171	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
172	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
173	     */
174	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        String idempotencyKey = currentIdempotencyKey();
180	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
181	            .map(this.clinicService::findOwnerById);
182	        if (existing.isPresent()) {
183	            return ownerResponse(existing.get(), HttpStatus.OK);
184	        }
185	        Owner owner = createOwner(ownerFieldsDto);
186	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
187	        return ownerResponse(owner, HttpStatus.CREATED);
188	    }
189	
190	    /**
191	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
192	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
193	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
194	     * originally created owner.
195	     *
196	     * @return the request's idempotency key, or {@code null} when none was supplied
197	     */
198	    private String currentIdempotencyKey() {
199	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
200	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
201	        }
202	        return null;
203	    }
204	
205	    /**
206	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
207	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
208	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
209	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
210	     * then respond" and the persisted owner is available to callers that need it beyond the response.
211	     *
212	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
213	     * @return the persisted owner, with its derived fields populated
214	     */
215	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
216	        normalizeAddress(ownerFieldsDto);
217	        rejectBlankOwnerFields(ownerFieldsDto);
218	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
219	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
220	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
221	        rejectCityAtCapacity(ownerFieldsDto.getCity());
222	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
223	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
224	        rejectDailyRegistrationLimit(registrationDate);
225	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
226	        ownerFieldsDto.setTelephone(normalizedTelephone);
227	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
228	        ownerFieldsDto.setEmail(normalizedEmail);
229	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
230	        owner.setRegistrationDate(registrationDate);
231	        owner.setCustomerCode(customerCode(owner));
232	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
233	        owner.setHouseholdId(householdId(owner));
234	        rejectDuplicateIdentity(owner);
235	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
236	        this.clinicService.saveOwner(owner);
237	        owner.setHouseholdSize(householdSize(owner));
238	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
239	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
240	            membershipLevel(owner), ownerMapper.membershipNumber(owner));
241	        emitOwnerCreatedEvent(owner);
242	        return owner;
243	    }
244	
245	    /**
246	     * Emits the immutable structured {@link OwnerCreatedEvent} for a just-created owner as a JSON
247	     * object on the {@code AUDIT} logger, alongside the human-readable audit line. The event is
248	     * stamped with the next {@link #CREATE_SEQUENCE} value and carries the owner's current
249	     * {@linkplain #primaryIdentifier(Owner) primary identifier} and reported
250	     * {@linkplain #membershipLevel(Owner) membership level}.
251	     *
252	     * @param owner the persisted owner just created
253	     */
254	    private void emitOwnerCreatedEvent(Owner owner) {
255	        OwnerCreatedEvent event = new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(),
256	            owner.getId(), primaryIdentifier(owner), membershipLevel(owner));
257	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
258	    }
259	
260	    /**
261	     * The owner's current primary identifier carried by the structured {@link OwnerCreatedEvent}.
262	     * Today an owner is identified by its {@code customerCode}; when the customer code is later
263	     * unified into the member id, this single method returns the member id instead, so the emitted
264	     * event switches to the new primary identifier without any other change to the create flow.
265	     *
266	     * @param owner the owner being audited
267	     * @return the owner's current primary identifier
268	     */
269	    private String primaryIdentifier(Owner owner) {
270	        return owner.getCustomerCode();
271	    }
272	
273	    /**
274	     * Builds the response for an owner: its derived-field DTO (see
275	     * {@link #toOwnerDtoWithDerivedFields(Owner)}) as the body and a {@code Location} header pointing at
276	     * the owner's canonical URL, returned with the given {@code status}. Assembling the response in one
277	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
278	     * path that returns an owner does so identically (differing only in the status it carries).
279	     *
280	     * @param owner the persisted owner to represent
281	     * @param status the HTTP status to return
282	     * @return the owner response with its body, {@code Location} header and status
283	     */
284	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
285	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
286	        HttpHeaders headers = new HttpHeaders();
287	        headers.setLocation(UriComponentsBuilder.newInstance()
288	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
289	        return new ResponseEntity<>(ownerDto, headers, status);
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
295	        return withOwner(ownerId, currentOwner -> {
296	            currentOwner.setAddress(ownerFieldsDto.getAddress());
297	            currentOwner.setCity(ownerFieldsDto.getCity());
298	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
299	            currentOwner.setLastName(ownerFieldsDto.getLastName());
300	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
301	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
302	            this.clinicService.saveOwner(currentOwner);
303	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
304	        });
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Transactional
309	    @Override
310	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
311	        return withOwner(ownerId, owner -> {
312	            owner.setDeleted(true);
313	            this.clinicService.saveOwner(owner);
314	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
315	        });
316	    }
317	
318	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
319	    @Override
320	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
321	        return withOwner(ownerId, owner -> {
322	            HttpHeaders headers = new HttpHeaders();
323	            Pet pet = petMapper.toPet(petFieldsDto);
324	            owner.setId(ownerId);
325	            pet.setOwner(owner);
326	            pet.getType().setName(null);
327	            this.clinicService.savePet(pet);
328	            PetDto petDto = petMapper.toPetDto(pet);
329	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
330	                .buildAndExpand(pet.getId()).toUri());
331	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
332	        });
333	    }
334	
335	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
336	    @Override
337	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
338	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
339	        if (currentOwner != null) {
340	            Pet currentPet = this.clinicService.findPetById(petId);
341	            if (currentPet != null) {
342	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
343	                currentPet.setName(petFieldsDto.getName());
344	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
345	                this.clinicService.savePet(currentPet);
346	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
347	            }
348	        }
349	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
350	    }
351	
352	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
353	    @Override
354	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
355	        HttpHeaders headers = new HttpHeaders();
356	        Visit visit = visitMapper.toVisit(visitFieldsDto);
357	        Pet pet = new Pet();
358	        pet.setId(petId);
359	        visit.setPet(pet);
360	        this.clinicService.saveVisit(visit);
361	        VisitDto visitDto = visitMapper.toVisitDto(visit);
362	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
363	            .buildAndExpand(visit.getId()).toUri());
364	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
365	    }
366	
367	
368	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
369	    @Override
370	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
371	        Owner owner = this.clinicService.findOwnerById(ownerId);
372	        if (owner != null) {
373	            Pet pet = owner.getPet(petId);
374	            if (pet != null) {
