427	    /**
428	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
429	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
430	     * routed through the controller so the create audit log and the single-owner response agree on one
431	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
432	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
433	     *
434	     * <p>Household ceiling: the reported level is capped at one above the current maximum
435	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
436	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
437	     * than the owner itself). With no existing household member no cap applies and the owner-local level
438	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
439	     * capped level), so it depends only on the members' own points and cannot recurse.
440	     *
441	     * @param owner the owner whose reported membership level is wanted
442	     * @return the owner's membership level, capped at one above its household maximum
443	     */
444	    private Integer membershipLevel(Owner owner) {
445	        int ownLevel = ownerMapper.membershipLevel(owner);
446	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
447	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
448	            .mapToInt(this::householdMemberLevel)
449	            .max();
450	        if (maxHouseholdLevel.isEmpty()) {
451	            return ownLevel;
452	        }
453	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
454	    }
