456	    /**
457	     * The owner-local membership level of a household member, used only as an input to the household
458	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
459	     * household size} is set from its household before the level is derived, so the member's household
460	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
461	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
462	     *
463	     * @param member an existing member of an owner's household
464	     * @return the member's owner-local membership level
465	     */
466	    private int householdMemberLevel(Owner member) {
467	        member.setHouseholdSize(householdSize(member));
468	        return ownerMapper.membershipLevel(member);
469	    }
