471	    /**
472	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
473	     * every later step - the required-field check, the persisted value and the response - sees the
474	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
475	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
476	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
477	     * steps that read the address.
478	     *
479	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
480	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
481	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
482	     * are preferred when present: the flat {@code address} returned is composed as the normalized
483	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
484	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
485	     * {@code address} retain its own normalized value.
486	     *
487	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
488	     */
489	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
490	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
491	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
492	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
493	        ownerFieldsDto.setAddressLine1(addressLine1);
494	        ownerFieldsDto.setAddressLine2(addressLine2);
495	        if (addressLine1 != null && !addressLine1.isBlank()) {
496	            String composed = addressLine2 != null && !addressLine2.isBlank()
497	                ? addressLine1 + " " + addressLine2
498	                : addressLine1;
499	            ownerFieldsDto.setAddress(composed);
500	        } else {
501	            ownerFieldsDto.setAddress(flatAddress);
502	        }
503	    }
