505	    /**
506	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
507	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
508	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
509	     * blank (e.g. {@code "   "}). The offending field names are reported through an
510	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
511	     * as a 400 response carrying an {@code errors} array of field names.
512	     *
513	     * @param ownerFieldsDto the submitted owner fields
514	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
515	     */
516	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
517	        List<String> blankFields = new ArrayList<>();
518	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
519	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
520	        addRequiredAddress(blankFields, ownerFieldsDto);
521	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
522	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
523	        if (!blankFields.isEmpty()) {
524	            throw new InvalidOwnerFieldsException(blankFields);
525	        }
526	    }
527	
528	    private void addIfBlank(List<String> blankFields, String field, String value) {
529	        if (value != null && value.isBlank()) {
530	            blankFields.add(field);
531	        }
532	    }
