534	    /**
535	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
536	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
537	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
538	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
539	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
540	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
541	     *
542	     * @param blankFields the accumulating list of blank required-field names
543	     * @param ownerFieldsDto the submitted owner fields
544	     */
545	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
546	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
547	            blankFields.add("address");
548	        }
