574	    /**
575	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
576	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
577	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
578	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
579	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
580	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
581	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
582	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
583	     *
584	     * @param city the city of the owner being created
585	     * @param postcode the supplied postcode, or {@code null} when omitted
586	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
587	     */
588	    private void rejectInvalidPostcode(String city, String postcode) {
589	        if (postcode == null || postcode.isBlank()) {
