599	    /**
600	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
601	     * the {@code customerCode}.
602	     */
603	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
604	
605	    /**
606	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
607	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
608	     * its {@code postcode} (falling back to its {@code city}) through the shared
609	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
610	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
611	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
612	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
613	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
614	     * distinct customer codes.
615	     *
616	     * @param owner the owner being created, with its telephone already normalized
617	     * @return the formatted, de-duplicated customer code
618	     */
619	    private String customerCode(Owner owner) {
620	        String region = Region.code(owner.getPostcode(), owner.getCity());
621	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
622	        String base = region + "-" + hash8;
623	        return deduplicateCustomerCode(base);
624	    }
625	
626	    /**
627	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
628	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
629	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
630	     * held by no existing owner.
631	     *
632	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
633	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
634	     */
635	    private String deduplicateCustomerCode(String base) {
636	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
637	            .map(Owner::getCustomerCode)
638	            .filter(java.util.Objects::nonNull)
639	            .collect(java.util.stream.Collectors.toSet());
640	        if (!existing.contains(base)) {
641	            return base;
642	        }
643	        int n = 2;
644	        while (existing.contains(base + "-" + n)) {
645	            n++;
646	        }
647	        return base + "-" + n;
648	    }
