767	    /**
768	     * The fixed list of public holidays that are not business days. A registration date that lands
769	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
770	     * business day, exactly as it is rolled forward off a weekend.
771	     */
772	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
773	        LocalDate.of(2026, 1, 1),
774	        LocalDate.of(2026, 1, 26),
775	        LocalDate.of(2026, 4, 25),
776	        LocalDate.of(2026, 12, 25),
777	        LocalDate.of(2026, 12, 28));
