779	    /**
780	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
781	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
782	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
783	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
784	     * value - whether supplied in the request or defaulted to the server date - is stored as the
785	     * next business day, and every value derived from the registration date (such as the membership
786	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
787	     *
788	     * @param date the effective registration date
789	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
790	     */
791	    private LocalDate businessDay(LocalDate date) {
792	        while (isNonBusinessDay(date)) {
793	            date = date.plusDays(1);
794	        }
795	        return date;
796	    }
