798	    /**
799	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
800	     *
801	     * @param date the date to test
802	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
803	     */
804	    private boolean isNonBusinessDay(LocalDate date) {
805	        DayOfWeek dayOfWeek = date.getDayOfWeek();
806	        return dayOfWeek == DayOfWeek.SATURDAY
807	            || dayOfWeek == DayOfWeek.SUNDAY
808	            || PUBLIC_HOLIDAYS.contains(date);
809	    }
