828	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
829	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
830	     * day's owners identically.
831	     *
832	     * @param date the registration date to count owners for
833	     * @return the number of existing owners registered on that day
834	     */
835	    private long ownersRegisteredOn(LocalDate date) {
836	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
