839	    /**
840	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
841	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
842	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
843	     */
844	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
