846	    /**
847	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
848	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
849	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
850	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
851	     * without a registration date, such as seed data) is never flagged.
852	     *
853	     * @param date the owner's registration date (the day it was created), or {@code null}
854	     * @return {@code true} if the day already holds more than the warning threshold of owners
855	     */
856	    private boolean bulkSignupWarning(LocalDate date) {
857	        if (date == null) {
858	            return false;
859	        }
860	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
861	    }
862	
863	    /**
864	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
865	     * The identity key is the SHA-256 hex digest over
866	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
867	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
868	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
869	     * owners with the same last name and postcode but <em>different</em> telephones have different
870	     * identity keys and are both allowed (the second is surfaced instead as a soft
871	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
872	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
873	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
874	     * reported through a {@link DuplicateOwnerIdentityException}, which the {@code ExceptionControllerAdvice}
875	     * renders as a 409 Conflict response.
876	     *
877	     * @param owner the fully-populated owner being created (telephone normalized, email set)
878	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
879	     */
880	    private void rejectDuplicateIdentity(Owner owner) {
881	        String key = identityKey(owner);
882	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
883	        if (duplicate) {
884	            throw new DuplicateOwnerIdentityException(key);
885	        }
886	    }
887	
888	    /**
889	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
890	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
891	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
892	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
893	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
894	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
895	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
896	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
897	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
898	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
899	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
900	     *
901	     * @param owner the fully-populated owner being created (telephone normalized)
902	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
903	     */
904	    private Integer possibleDuplicateOf(Owner owner) {
905	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
906	            return null;
907	        }
908	        String key = identityKey(owner);
909	        String lastNameSoundex = soundex.encode(owner.getLastName());
910	        return this.clinicService.findAllOwners().stream()
911	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
912	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
913	                && !key.equals(identityKey(existing)))
914	            .map(Owner::getId)
915	            .filter(java.util.Objects::nonNull)
916	            .findFirst()
917	            .orElse(null);
918	    }
919	
920	    /**
921	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
922	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
923	     * the owner's telephone reduced to its canonical E.164 form (see
924	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
925	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
926	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
927	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
928	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
929	     * value across owners.
930	     *
931	     * @param owner the owner to derive the identity key for
932	     * @return the owner's identity key, a 64-character lower-case hex string
933	     */
934	    private String identityKey(Owner owner) {
935	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
936	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
937	        String email = normalizedEmail == null ? "" : normalizedEmail;
938	        String lastNameSoundex = soundex.encode(owner.getLastName());
939	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
940	    }
941	
942	    /**
943	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
944	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
945	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
946	     * checks reduce both an existing owner and the owner being created to the same canonical key;
947	     * this returns the matched existing owner itself, so a caller can either reject the collision or
948	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
949	     * collision with only a deleted owner is not reported and the create is allowed.
950	     *
951	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
952	     * @param key the canonical key of the owner being created
953	     * @return the first existing owner sharing the key, or empty when none does
954	     */
955	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
956	        return this.clinicService.findAllOwners().stream()
957	            .filter(owner -> !owner.isDeleted())
958	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
959	            .findFirst();
960	    }
961	
962	    /**
963	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
964	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
965	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
966	     * being created to the same canonical key and reject a match.
967	     *
968	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
969	     * @param key the canonical key of the owner being created
970	     * @return {@code true} if some existing owner shares the key
971	     */
972	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
973	        return findExistingOwner(keyExtractor, key).isPresent();
974	    }
975	
976	    /**
977	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
978	     * count-based rules - the per-city capacity, the per-day create limit and the derived
979	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
980	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
981	     * place and each rule supplies just its own predicate.
982	     *
983	     * @param predicate the condition an owner must satisfy to be counted
984	     * @return the number of existing owners that satisfy the predicate
985	     */
986	    private long countOwners(Predicate<Owner> predicate) {
987	        return this.clinicService.findAllOwners().stream()
988	            .filter(predicate)
989	            .count();
990	    }
991	
992	    /**
993	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
994	     * shared {@code householdId}.
995	     */
996	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
997	
998	    /**
999	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1000	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1001	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1002	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1003	     *
1004	     * @param value the raw field value, or {@code null}
1005	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1006	     */
1007	    private String canonicalizeHousehold(String value) {
1008	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1009	    }
1010	
1011	    /**
1012	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1013	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1014	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1015	     * for the last-name normalization), so every owner with the same last name and postcode -
1016	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1017	     * a postcode have no household basis and are given no household id ({@code null}).
1018	     *
1019	     * @param owner the owner being created
1020	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1021	     */
1022	    /**
1023	     * Counts the owners in the given owner's household: the existing owners that share its
1024	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1025	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1026	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1027	     * household factor of the owner's membership points.
1028	     *
1029	     * @param owner the owner whose household size is being derived
1030	     * @return the number of owners in the owner's household (at least {@code 1})
1031	     */
1032	    private int householdSize(Owner owner) {
1033	        if (owner.getHouseholdId() == null) {
1034	            return 1;
1035	        }
1036	        return householdMembers(owner).size();
1037	    }
1038	
1039	    /**
1040	     * The existing owners that make up the given owner's household: those sharing its
1041	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1042	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1043	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1044	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1045	     * counts it among its household, while one taken before the save sees only the owners already
1046	     * present. Holding the household lookup in one place lets every household-derived value read the
1047	     * same set of members.
1048	     *
1049	     * @param owner the owner whose household members are wanted
1050	     * @return the owners sharing the owner's household, or an empty list when it has no household
1051	     */
1052	    private List<Owner> householdMembers(Owner owner) {
1053	        String household = owner.getHouseholdId();
1054	        if (household == null) {
1055	            return List.of();
1056	        }
1057	        return this.clinicService.findAllOwners().stream()
1058	            .filter(existing -> household.equals(existing.getHouseholdId()))
1059	            .toList();
1060	    }
1061	
1062	    private String householdId(Owner owner) {
1063	        String postcode = owner.getPostcode();
1064	        if (postcode == null || postcode.isBlank()) {
1065	            return null;
1066	        }
1067	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1068	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1069	    }
1070	
1071	    /**
1072	     * Number of leading hex characters of the household hash retained as the shared
1073	     * {@code householdId}.
1074	     */
1075	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1076	}
